<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {LayoutDashboard,Package,Tags,ShoppingCart,Store,Plus,Search,Pencil,Archive,ArrowLeft,Save,Upload,ChevronRight,AlertTriangle,RefreshCcw} from 'lucide-vue-next';import {api,idr,uploadApi} from '../api';import {useSession,useUi} from '../stores';const props=defineProps<{section:'overview'|'products'|'product-form'|'categories'|'orders'|'order-detail'}>();const route=useRoute(),router=useRouter(),session=useSession(),ui=useUi(),data=ref<any>(null),categories=ref<any[]>([]),loading=ref(true),error=ref(''),search=ref(''),categoryModal=ref(false),categoryForm=ref({id:'',name:'',isActive:true}),productForm=ref<any>({name:'',sku:'',description:'',categoryId:'',price:0,stock:0,isActive:true,imageUrl:''}),saving=ref(false);const titles:any={overview:['Store Overview & Analytics','Monitor daily performance and store operations.'],products:['Product Inventory','Manage catalog, price, visibility, and stock.'],'product-form':['Product Editor','Create or update a catalog item.'],categories:['Category Management','Organize the public storefront taxonomy.'],orders:['Order Management','Process paid orders through fulfillment.'],'order-detail':['Order Detail','Review payment and fulfillment information.']};async function guard(){if(!session.user)await session.load();if(!session.user)return router.push('/login');if(session.user.role!=='ADMIN')return router.push('/')}async function load(){loading.value=true;error.value='';await guard();try{if(props.section==='overview')data.value=await api('/admin/dashboard/overview');if(props.section==='products')data.value=await api('/admin/products');if(props.section==='categories')data.value=await api('/admin/categories');if(props.section==='orders')data.value=await api('/admin/orders');if(props.section==='order-detail')data.value=await api(`/admin/orders/${route.params.id}`);if(props.section==='product-form'){categories.value=await api('/admin/categories');if(route.params.id){const p:any=await api(`/admin/products/${route.params.id}`);productForm.value={name:p.name,sku:p.sku,description:p.description,categoryId:p.categoryId,price:Number(p.price),stock:p.stock,isActive:p.isActive,imageUrl:p.images[0]?.imageUrl??''}}else productForm.value={name:'',sku:'',description:'',categoryId:'',price:0,stock:0,isActive:true,imageUrl:''}}}catch(e:any){error.value=e.message}finally{loading.value=false}}async function saveProduct(){saving.value=true;try{const path=route.params.id?`/admin/products/${route.params.id}`:'/admin/products',method=route.params.id?'PATCH':'POST';await api(path,{method,body:JSON.stringify(productForm.value)});ui.toast('Product saved');router.push('/admin/products')}catch(e:any){error.value=e.message}finally{saving.value=false}}async function uploadImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const form=new FormData();form.append('image',file);try{const result=await uploadApi<{url:string}>('/admin/uploads/products',form);productForm.value.imageUrl=`http://localhost:3000${result.url}`;ui.toast('Image uploaded')}catch(e:any){ui.toast(e.message,'error')}}async function archiveProduct(p:any){if(!confirm(`Archive ${p.name}?`))return;await api(`/admin/products/${p.id}`,{method:'DELETE'});ui.toast('Product archived');load()}async function restoreProduct(p:any){await api(`/admin/products/${p.id}`,{method:'PATCH',body:JSON.stringify({isActive:true})});ui.toast('Product restored');load()}function editCategory(c?:any){categoryForm.value=c?{id:c.id,name:c.name,isActive:c.isActive}:{id:'',name:'',isActive:true};categoryModal.value=true}async function saveCategory(){try{const path=categoryForm.value.id?`/admin/categories/${categoryForm.value.id}`:'/admin/categories',method=categoryForm.value.id?'PATCH':'POST';await api(path,{method,body:JSON.stringify({name:categoryForm.value.name,isActive:categoryForm.value.isActive})});categoryModal.value=false;categoryForm.value={id:'',name:'',isActive:true};ui.toast('Category saved');load()}catch(e:any){ui.toast(e.message,'error')}}async function archiveCategory(c:any){if(!confirm(`Archive ${c.name}?`))return;await api(`/admin/categories/${c.id}`,{method:'DELETE'});ui.toast('Category archived');load()}const nextStatus=(status:string)=>({PENDING:'PROCESSING',PROCESSING:'SHIPPED',SHIPPED:'DELIVERED'} as any)[status];async function progressOrder(){const next=nextStatus(data.value.fulfillmentStatus);if(!next)return;try{data.value=await api(`/admin/orders/${data.value.id}/fulfillment`,{method:'PATCH',body:JSON.stringify({status:next})});ui.toast(`Order moved to ${next}`);load()}catch(e:any){ui.toast(e.message,'error')}}onMounted(load);watch(()=>[props.section,route.params.id],load);</script>
<template><div class="admin-app"><aside class="admin-sidebar"><RouterLink to="/admin" class="admin-brand"><span>S</span><div><b>SHOPORA</b><small>MANAGEMENT PORTAL</small></div></RouterLink><nav><small>WORKSPACE</small><RouterLink to="/admin"><LayoutDashboard/> Overview</RouterLink><RouterLink to="/admin/orders"><ShoppingCart/> Orders</RouterLink><RouterLink to="/admin/products"><Package/> Products</RouterLink><RouterLink to="/admin/categories"><Tags/> Categories</RouterLink></nav><div class="admin-profile"><div>{{session.user?.name.slice(0,1)}}</div><span><b>{{session.user?.name}}</b><small>Administrator</small></span></div><RouterLink class="store-link" to="/"><Store/> Return to Store</RouterLink></aside><main class="admin-content"><header class="admin-topbar"><div><small>PRIVATE WORKSPACE / {{section.toUpperCase()}}</small><h1>{{titles[section][0]}}</h1><p>{{titles[section][1]}}</p></div><RouterLink v-if="section==='products'" class="admin-primary" to="/admin/products/new"><Plus/> Add New Product</RouterLink><button v-if="section==='categories'" class="admin-primary" @click="editCategory()"><Plus/> Add Category</button></header><p v-if="error" class="admin-alert">{{error}}</p><div v-if="loading" class="admin-loading"><span></span><p>Loading workspace…</p></div><template v-else><template v-if="section==='overview'"><div class="admin-metrics"><article><small>PAID REVENUE</small><b>{{idr(data.paidRevenue)}}</b><span>Confirmed transactions</span></article><article><small>TOTAL ORDERS</small><b>{{data.totalOrders}}</b><span>All-time volume</span></article><article><small>ACTIVE PRODUCTS</small><b>{{data.activeProducts}}</b><span>Visible in storefront</span></article><article><small>PENDING ORDERS</small><b>{{data.pendingOrders}}</b><span>Awaiting action</span></article></div><div class="admin-dashboard-grid"><section class="admin-panel"><header><h2>Recent Orders</h2><RouterLink to="/admin/orders">View all <ChevronRight/></RouterLink></header><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Fulfillment</th></tr></thead><tbody><tr v-for="o in data.recentOrders" @click="router.push(`/admin/orders/${o.id}`)"><td><b>{{o.orderNumber}}</b></td><td>{{o.user.name}}</td><td>{{idr(o.totalAmount)}}</td><td><span class="admin-status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span></td><td>{{o.fulfillmentStatus}}</td></tr><tr v-if="!data.recentOrders.length"><td colspan="5">No orders yet.</td></tr></tbody></table></div></section><section class="admin-panel stock-panel"><header><h2>Low Stock</h2><AlertTriangle/></header><article v-for="p in data.lowStock"><div><b>{{p.name}}</b><small>{{p.sku}}</small></div><strong>{{p.stock}} units</strong></article><p v-if="!data.lowStock.length" class="admin-empty">Inventory levels are healthy.</p></section></div></template><section v-if="section==='products'" class="admin-panel"><header class="panel-tools"><div class="admin-search"><Search/><input v-model="search" placeholder="Search product or SKU"/></div><span>{{data.length}} products</span></header><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>SKU</th><th>Price</th><th>Stock</th><th>Status</th><th class="right">Actions</th></tr></thead><tbody><tr v-for="p in data.filter((p:any)=>(p.name+p.sku).toLowerCase().includes(search.toLowerCase()))"><td class="product-cell"><img :src="p.images[0]?.imageUrl"/><b>{{p.name}}</b></td><td>{{p.category.name}}</td><td class="mono">{{p.sku}}</td><td>{{idr(p.price)}}</td><td :class="{critical:p.stock<=5}">{{p.stock}}</td><td><span class="admin-status" :class="p.isActive?'active':'archived'">{{p.isActive?'ACTIVE':'ARCHIVED'}}</span></td><td class="row-actions"><RouterLink :to="`/admin/products/${p.id}/edit`"><Pencil/></RouterLink><button v-if="p.isActive" @click="archiveProduct(p)"><Archive/></button><button v-else title="Restore" @click="restoreProduct(p)"><RefreshCcw/></button></td></tr></tbody></table></div></section><section v-if="section==='product-form'" class="product-editor"><RouterLink to="/admin/products" class="admin-back"><ArrowLeft/> Back to products</RouterLink><form @submit.prevent="saveProduct"><section class="admin-panel"><header><h2>Product Information</h2></header><div class="admin-form-grid"><label>Product Name<input v-model="productForm.name" required minlength="2"/></label><label>SKU<input v-model="productForm.sku" required minlength="2"/></label><label>Category<select v-model="productForm.categoryId" required><option value="" disabled>Select category</option><option v-for="c in categories.filter(c=>c.isActive)" :value="c.id">{{c.name}}</option></select></label><label>Price (IDR)<input v-model.number="productForm.price" type="number" min="0" required/></label><label>Stock Units<input v-model.number="productForm.stock" type="number" min="0" required/></label><label class="toggle-label"><input v-model="productForm.isActive" type="checkbox"/> Product is active</label><label class="full">Description<textarea v-model="productForm.description" required minlength="10" rows="6"></textarea></label></div></section><section class="admin-panel"><header><h2>Product Image</h2></header><div class="image-editor"><img v-if="productForm.imageUrl" :src="productForm.imageUrl"/><div v-else class="image-placeholder"><Upload/></div><div><label>Image URL<input v-model="productForm.imageUrl" type="url" placeholder="https://..."/></label><label class="upload-button"><Upload/> Upload JPEG, PNG, or WebP<input type="file" accept="image/jpeg,image/png,image/webp" @change="uploadImage"/></label></div></div></section><div class="editor-actions"><RouterLink class="admin-secondary" to="/admin/products">Cancel</RouterLink><button class="admin-primary" :disabled="saving"><Save/> {{saving?'Saving…':'Save Product'}}</button></div></form></section><section v-if="section==='categories'" class="admin-panel"><header><h2>Catalog Categories</h2><span>{{data.length}} categories</span></header><div class="category-admin-grid"><article v-for="c in data"><div><span class="category-icon"><Tags/></span><div><h3>{{c.name}}</h3><p>/{{c.slug}} · {{c._count.products}} products</p></div></div><span class="admin-status" :class="c.isActive?'active':'archived'">{{c.isActive?'ACTIVE':'ARCHIVED'}}</span><div><button @click="editCategory(c)"><Pencil/></button><button v-if="c.isActive" @click="archiveCategory(c)"><Archive/></button></div></article></div></section><section v-if="section==='orders'" class="admin-panel"><header class="panel-tools"><div class="admin-search"><Search/><input v-model="search" placeholder="Search order or customer"/></div><span>{{data.length}} orders</span></header><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Items</th><th>Total</th><th>Payment</th><th>Fulfillment</th><th></th></tr></thead><tbody><tr v-for="o in data.filter((o:any)=>(o.orderNumber+o.user.name+o.user.email).toLowerCase().includes(search.toLowerCase()))"><td><b>{{o.orderNumber}}</b></td><td>{{o.user.name}}<small class="block">{{o.user.email}}</small></td><td>{{new Date(o.createdAt).toLocaleDateString('id-ID')}}</td><td>{{o.items.length}}</td><td>{{idr(o.totalAmount)}}</td><td><span class="admin-status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span></td><td>{{o.fulfillmentStatus}}</td><td><RouterLink :to="`/admin/orders/${o.id}`"><ChevronRight/></RouterLink></td></tr></tbody></table></div></section><section v-if="section==='order-detail'&&data" class="admin-order-detail"><RouterLink to="/admin/orders" class="admin-back"><ArrowLeft/> Back to orders</RouterLink><header class="admin-panel order-admin-head"><div><small>ORDER NUMBER</small><h2>{{data.orderNumber}}</h2><p>{{new Date(data.createdAt).toLocaleString('id-ID')}}</p></div><div><span class="admin-status" :class="data.paymentStatus.toLowerCase()">{{data.paymentStatus}}</span><span class="admin-status active">{{data.fulfillmentStatus}}</span></div></header><div class="admin-dashboard-grid"><section class="admin-panel"><header><h2>Order Items</h2></header><article v-for="i in data.items" class="admin-order-line"><div><b>{{i.productName}}</b><small>{{i.productSku}} · {{i.quantity}} × {{idr(i.unitPrice)}}</small></div><strong>{{idr(i.lineTotal)}}</strong></article><div class="admin-totals"><p><span>Subtotal</span><b>{{idr(data.subtotal)}}</b></p><p><span>Shipping</span><b>{{idr(data.shippingFee)}}</b></p><p><span>Total</span><strong>{{idr(data.totalAmount)}}</strong></p></div></section><aside class="admin-panel"><header><h2>Customer & Shipping</h2></header><p><b>{{data.user.name}}</b><br/>{{data.user.email}}</p><p>{{data.shippingAddressSnapshot.recipientName}}<br/>{{data.shippingAddressSnapshot.addressLine}}<br/>{{data.shippingAddressSnapshot.city}}, {{data.shippingAddressSnapshot.province}} {{data.shippingAddressSnapshot.postalCode}}</p><button v-if="nextStatus(data.fulfillmentStatus)" class="admin-primary wide" :disabled="data.paymentStatus!=='PAID'" @click="progressOrder">Move to {{nextStatus(data.fulfillmentStatus)}}</button><small v-if="data.paymentStatus!=='PAID'" class="admin-help">Order must be paid before fulfillment.</small></aside></div></section></template></main><Teleport to="body"><div v-if="categoryModal" class="modal-shell admin-modal-shell"><button class="modal-backdrop" @click="categoryModal=false"></button><form class="modal-card" @submit.prevent="saveCategory"><header><div><small>CATALOG TAXONOMY</small><h2>{{categoryForm.id?'Edit Category':'Add Category'}}</h2></div><button type="button" @click="categoryModal=false">×</button></header><label>Category Name<input v-model="categoryForm.name" required minlength="2"/></label><label class="check"><input v-model="categoryForm.isActive" type="checkbox"/> Active category</label><footer><button type="button" class="admin-secondary" @click="categoryModal=false">Cancel</button><button class="admin-primary">Save Category</button></footer></form></div></Teleport></div></template>
